<?php
/**
 * Global CSS + hides theme chrome on the custom order-tracking pages
 *
 * @package TV_Board_Plugin
 */

if (!defined('ABSPATH')) exit; // No direct access

add_action('wp_head', function() {
    $custom_pages = ['track-your-order', 'order-tv', 'counter-entry', 'kitchen-display', 'pickup-display'];
    $is_custom = false;
    foreach ($custom_pages as $page) {
        if (strpos($_SERVER['REQUEST_URI'], $page) !== false) { $is_custom = true; break; }
    }
    if (!$is_custom) return;
    ?>
    <style>
@font-face { font-family: 'AuthorMedium'; src: url('data:font/ttf;base64,') format('truetype'); font-weight: normal; }
@font-face { font-family: 'AuthorMedium'; src: url('data:font/ttf;base64,') format('truetype'); font-weight: normal; }
@font-face { font-family: 'AuthorMedium'; src: url('data:font/ttf;base64,') format('truetype'); font-weight: normal; }
@font-face { font-family: 'Cairo'; src: url('data:font/ttf;base64,') format('truetype'); font-weight: 400; }
@font-face { font-family: 'Cairo'; src: url('data:font/ttf;base64,') format('truetype'); font-weight: 700; }
@import url(https://db.onlinewebfonts.com/c/d5233458993778436b3dbba291fdaf18?family=Tinta+Arabic);
</style>
    <style>
        header:not(.custom-nav-bar), footer, .wp-block-template-part, .site-header, .site-footer,
        .wp-block-navigation, .primary-menu-container, .wp-block-site-title, .wp-block-site-logo, .site-header .site-branding { 
            display: none !important; visibility: hidden !important; height: 0 !important; padding: 0 !important; margin: 0 !important;
        }
        
        /* Brand Colors Applied Across All Headers */
        .custom-nav-bar { background: #281a42; padding: 1.25rem 3rem; display: flex; justify-content: space-between; align-items: center; border-bottom: 3px solid #f9841f; }
        .header-brand { display: flex; flex-direction: column; gap: 0.15rem; }
        .brand-title { font-family: sans-serif; font-size: 2rem; color: #fff; margin: 0; line-height: 1.1; letter-spacing: 0.03em; }
        .status-monitor { color: #f9841f; font-size: 0.8rem; font-weight: 700; display: flex; align-items: center; gap: 0.25rem; font-family: sans-serif; letter-spacing: 0.05em; }
        .header-actions { display: flex; align-items: center; gap: 1.5rem; font-family: sans-serif; }
        .header-time { font-size: 1.8rem; font-weight: 900; color: #fff; letter-spacing: 0.02em; }
        
        main { min-height: 80vh; }
        .ewd-otp-full-display { background: linear-gradient(135deg, #281a42 0%, #3d2864 100%) !important; border-radius: 16px !important; padding: 2rem !important; color: white !important; width: 100% !important; box-sizing: border-box !important; margin-top: 1rem !important; }
        .ewd-otp-tracking-graphic, .ewd-otp-statuses, .ewd-otp-update-notice { display: none !important; }
        
        /* Timeline UI System Settings */
        .order-progress-container { display: none; background: linear-gradient(135deg, #281a42 0%, #3d2864 100%); padding: 3rem 2rem; border-radius: 16px; margin: 0 0 1.5rem 0; color: white; border: 1px solid rgba(249, 132, 31, 0.2); }
        .order-progress-container.visible { display: block; }
        .order-header { text-align: center; margin-bottom: 2.5rem; }
        .order-header h3 { font-family: sans-serif; font-size: 2rem; color: #fff; margin: 0; letter-spacing: 0.02em; }
        .order-number { font-family: sans-serif; font-size: 2.75rem; font-weight: 900; color: #f9841f; margin: 0.5rem 0; }
        
        .progress-timeline { display: flex; justify-content: space-between; align-items: flex-start; position: relative; margin: 2rem 0; }
        .progress-timeline::before { content: ""; position: absolute; top: 24px; left: 0; right: 0; height: 3px; background: #404040; z-index: 1; }
        .progress-timeline.in-progress::before { background: linear-gradient(90deg, #f9841f 0%, #f9841f var(--progress-width, 0%), #404040 var(--progress-width, 0%), #404040 100%); }
        .progress-step { display: flex; flex-direction: column; align-items: center; flex: 1; position: relative; z-index: 2; }
        .progress-step-circle { width: 48px; height: 48px; border-radius: 50%; background: #404040; border: 3px solid #281a42; display: flex; align-items: center; justify-content: center; font-weight: bold; margin-bottom: 1rem; color: rgba(255, 255, 255, 0.6); font-family: sans-serif; transition: all 0.3s ease; }
        .progress-step-circle.active { background: #f9841f; border-color: #f9841f; color: #fff; transform: scale(1.15); }
        .progress-step-circle.completed { background: #4caf50; border-color: #4caf50; color: white; }
        .progress-timeline.canceled .progress-step-circle { background: #666; border-color: #666; color: rgba(255,255,255,0.4); transform: none; }
        .progress-timeline.canceled::before { background: #404040 !important; }
        .cancel-toast { position: fixed; bottom: 2rem; left: 50%; transform: translateX(-50%) translateY(120px); background: linear-gradient(135deg, #b71c1c 0%, #d32f2f 100%); color: #fff; padding: 1rem 2rem; border-radius: 14px; box-shadow: 0 12px 40px rgba(183,28,28,0.5); display: flex; align-items: center; gap: 0.75rem; z-index: 9999; opacity: 0; transition: transform 0.4s cubic-bezier(0.175,0.885,0.32,1.275), opacity 0.4s ease; pointer-events: none; max-width: 90vw; font-family: sans-serif; }
        .cancel-toast.show { transform: translateX(-50%) translateY(0); opacity: 1; pointer-events: auto; }
        .cancel-toast-icon { font-size: 1.6rem; flex-shrink: 0; }
        .cancel-toast-body { display: flex; flex-direction: column; gap: 0.15rem; }
        .cancel-toast-title { font-weight: 900; font-size: 1rem; letter-spacing: 0.02em; }
        .cancel-toast-sub { font-size: 0.82rem; color: rgba(255,255,255,0.8); font-weight: 600; }
        .progress-step-label { font-family: sans-serif; font-size: 0.95rem; text-align: center; font-weight: 700; color: #d0d0d0; }
        .progress-step.active .progress-step-label { color: #fff; }
        
        .order-status-message { text-align: center; margin-top: 2rem; padding-top: 2rem; border-top: 1px solid rgba(255,255,255,0.2); }
        .status-text { font-family: sans-serif; font-size: 1.3rem; color: #f9841f; font-weight: 700; }
        
        .ewd-otp-tracking-form-div label, .ewd-otp-tracking-form-div p { font-family: sans-serif; color: #d0d0d0 !important; font-weight: 700 !important; }
        .ewd-otp-tracking-form-div input[type="text"], .ewd-otp-tracking-form-div input[type="number"] { font-family: sans-serif; background: rgba(255, 255, 255, 0.08) !important; border: 1px solid rgba(249, 132, 31, 0.5) !important; border-radius: 8px !important; padding: 12px 16px !important; width: 300px !important; max-width: 100% !important; color: #ffffff !important; outline: none !important; }
        .ewd-otp-tracking-form-div input[type="text"]:focus, .ewd-otp-tracking-form-div input[type="number"]:focus { background: #ffffff !important; border-color: #f9841f !important; color: #281a42 !important; }
        .ewd-otp-tracking-form-div input[type="submit"], .ewd-otp-tracking-form-div button[type="submit"] { font-family: sans-serif; background: #f9841f !important; color: white !important; border: none !important; border-radius: 8px !important; padding: 10px 28px !important; font-weight: 700 !important; margin-top: 12px !important; display: block !important; cursor: pointer !important; }
        
        @media (max-width: 768px) {
            .custom-nav-bar { flex-direction: column; gap: 1rem; text-align: center; padding: 1.5rem 1rem; }
            .progress-step-circle { width: 40px; height: 40px; }
            .order-header h3 { font-size: 1.5rem; }
            .order-number { font-size: 2.25rem; }
        }
    </style>
    <?php
});

